NavigationDecision handle3dsNavigation(NavigationRequest request) {
  if (request.url.startsWith('https://checkout.thawani.om/pay/callback')) {
    final uri = Uri.parse(request.url);
    final status = uri.queryParameters['status'];
    final txId = uri.queryParameters['transaction_id'];
    _completePayment(status: status, txId: txId);
    return NavigationDecision.prevent;
  }
  return NavigationDecision.navigate;
}

String generateSignature({
  required String secret,
  required String method,
  required String path,
  required int timestamp,
  required String body,
}) {
  final payload = '$method|$path|$timestamp|$body';
  final hmac = Hmac(sha256, utf8.encode(secret));
  return hmac.convert(utf8.encode(payload)).toString();
}

