Future<Box<TransactionRecord>> openEncryptedBox() async {
  final secureStorage = FlutterSecureStorage();
  String? keyString = await secureStorage.read(key: 'hive_key');
  if (keyString == null) {
    final key = Hive.generateSecureKey();
    await secureStorage.write(key: 'hive_key', value: base64UrlEncode(key));
    keyString = base64UrlEncode(key);
  }
  return await Hive.openBox<TransactionRecord>(
    'transactions',
    encryptionCipher: HiveAesCipher(base64Url.decode(keyString)),
  );
}
